fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and select 'Archiving', then click 'Run History' in the app's left navigation. The page shows summary metric cards (Total Runs, Records Archived, Storage Used, Last Run) and a 'Run History' list of run cards. Click one of the run cards. Success is a slide-in drawer opening on the right titled 'Run Details' showing the run's Configuration/Status/Started/Duration, a stats row (Archived / Failed / Skipped), and a 'Per-Record Results' area (a table or a 'No detail records found' message). Confirm the drawer can be closed via its X button or by clicking the backdrop. If there are no runs, seeing the 'No archive runs found' empty state is acceptable success. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
